package com.hbm.client.radiolysis;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.fluid.*;import com.hbm.item.battery.BatteryItem;import com.hbm.item.fluid.client.FluidInfo;import com.hbm.machine.radiolysis.*;import com.hbm.machine.rtg.RtgContent;import java.util.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.item.ItemStack;
/** Source230x166 texture, actual15machine slots, exact tank/electricity/info rectangles. */
public final class RadiolysisScreen extends LegacyContainerScreen<RadiolysisMenu> {
 private static final ResourceLocation UTILITY=RadiolysisContent.id("textures/gui/gui_utility.png");
 public RadiolysisScreen(RadiolysisMenu menu,Inventory inventory,Component title){super(menu,inventory,title,RadiolysisContent.id("textures/gui/gui_radiolysis.png"),230,166);}
 private RadiolysisBlockEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position()) instanceof RadiolysisBlockEntity machine?machine:null;}
 @Override protected void renderLabels(GuiGraphics graphics,int x,int y){graphics.drawString(font,title,88-font.width(title)/2,6,4210752,false);graphics.drawString(font,playerInventoryTitle,8,72,4210752,false);}
 @Override protected void renderBg(GuiGraphics graphics,float partial,int x,int y){super.renderBg(graphics,partial,x,y);int power=(int)(menu.power()*34/RadiolysisBlockEntity.MAX_POWER);drawLegacyRegion(graphics,8,51-power,240,34-power,16,power);var machine=machine();if(machine!=null){tank(graphics,machine.tanks[0],61,69,8,52);tank(graphics,machine.tanks[1],87,33,12,16);tank(graphics,machine.tanks[2],87,69,12,16);}graphics.blit(UTILITY,leftPos-16,topPos+16,8,32,16,16,256,256);graphics.blit(UTILITY,leftPos-16,topPos+34,8,0,16,16,256,256);graphics.blit(UTILITY,leftPos-16,topPos+52,24,0,16,16,256,256);}
 private void tank(GuiGraphics graphics,FluidTank tank,int x,int bottom,int width,int maximum){int height=tank.getFill()*maximum/tank.getMaxFill();if(height<=0)return;int color=tank.getTankType().getTint();graphics.setColor((color>>16&255)/255F,(color>>8&255)/255F,(color&255)/255F,1);graphics.blit(tank.getTankType().getTexture(),leftPos+x,topPos+bottom-height,0,16-height,width,height,16,16);graphics.setColor(1,1,1,1);}
 private static List<Component> split(Component text){return Arrays.stream(text.getString().split("\\$",-1)).map(Component::literal).map(Component.class::cast).toList();}
 @Override public void render(GuiGraphics graphics,int x,int y,float partial){super.render(graphics,x,y,partial);var machine=machine();if(machine!=null){if(legacyInfoHovered(x,y,61,17,8,52))info(graphics,machine.tanks[0],x,y);if(legacyInfoHovered(x,y,87,17,12,16))info(graphics,machine.tanks[1],x,y);if(legacyInfoHovered(x,y,87,53,12,16))info(graphics,machine.tanks[2],x,y);}if(legacyInfoHovered(x,y,8,17,16,34))graphics.renderTooltip(font,Component.literal(BatteryItem.shortNumber(menu.power())+"/"+BatteryItem.shortNumber(RadiolysisBlockEntity.MAX_POWER)+"HE"),x,y);if(legacyInfoHovered(x,y,-16,16,16,16))graphics.renderComponentTooltip(font,split(Component.translatable("desc.gui.radiolysis.desc")),leftPos-8,topPos+32);if(legacyInfoHovered(x,y,-16,34,16,16))graphics.renderComponentTooltip(font,split(Component.translatable("desc.gui.rtg.heat",menu.heat())),leftPos-8,topPos+50);if(legacyInfoHovered(x,y,-16,52,16,16)){var lines=new ArrayList<Component>();lines.add(Component.translatable("desc.gui.rtg.pellets"));for(var holder:RtgContent.PELLETS){var pellet=holder.get();lines.add(Component.translatable("desc.gui.rtg.pelletPower",pellet.getName(new ItemStack(pellet)),pellet.heat()*10));}graphics.renderComponentTooltip(font,lines,leftPos-8,topPos+68);}}
 private void info(GuiGraphics graphics,FluidTank tank,int x,int y){var lines=new ArrayList<Component>();lines.add(tank.getTankType().displayName());lines.add(Component.literal(tank.getFill()+"/"+tank.getMaxFill()+"mB"));FluidInfo.append(tank.getTankType(),lines,hasShiftDown());graphics.renderComponentTooltip(font,lines,x,y);}
}
